/**
 * Text replacements applied by the cleaner, as [from, to] pairs.
 *
 * Matching is longest-first at each position (see trie.js), so `\\log_10`
 * wins over `\\log`. Unless an entry ends with `true` ("case sensitive"),
 * its all-lower, ALL-UPPER and Capitalised spellings are added too —
 * so `Max` also covers `max` and `MAX`, but an exact entry always beats a
 * generated variant.
 *
 * Two passes use two tables:
 *
 *   WORD_REPLACEMENTS    run while spaces are still in the text, so entries
 *                        can rely on word boundaries (` And `, ` C `).
 *   SYMBOL_REPLACEMENTS  run after all whitespace has been removed: LaTeX
 *                        commands, unicode symbols, programming spellings.
 *                        The trig spellings are generated in trigReplacements().
 */

export const WORD_REPLACEMENTS = [
    [" And ", " &  "],
    [" Or ", " ∨ "],
    [" Not In ", " ∉ "],
    [" Nor ", "  \\nor  "],
    [" Xor ", "  \\xor  "],
    [" Nand ", "  \\nand  "],
    [" In ", " ∈ "],
    [" Mod ", " \\mod "],
    [" % ", "%"],
    [" Perm ", "\\perm "],
    [" P ", "\\perm", true],
    [" Comb ", "\\comb "],
    [" C ", "\\comb", true],
    [" choose ", "\\comb "],
    ["! ", "!_"],
    ["\\in ", "∈"],
    ["\\notin ", "∉"],
    ["\\not\\in ", "∉"],
    ["\\to ", "→"],
    ["===", "=...="],
];

