/**
 * Every way of writing the six trig functions, their hyperbolic forms and
 * their inverses: `\\sin`, `Math.sin(`, `sin^{-1}`, `\\asinh`, `Math.atanh(`...
 */
export function trigReplacements() {
    const out = [];
    const variants = (from, to) => {
        out.push([from, to], [from + '(', to + '(']);
    };
    for (const t of ['sin', 'cos', 'tan', 'cot', 'csc', 'sec']) {
        out.push(['Math.' + t + '(', t + '('], ['\\' + t + '(', t + '('], ['\\' + t, t]);
        if (!['sin', 'cos', 'tan'].includes(t)) continue;
        for (const h of ['', 'h']) {
            const fn = t + h, inv = 'arc' + t + h;
            if (h) {
                variants('Math.' + fn, fn);
                variants('\\' + fn, fn);
            }
            for (const power of ['^-1', '^{-1}', '-1']) {
                variants('\\' + fn + power, inv);
                variants(fn + power, inv);
                if (!h) variants('Math.' + fn + power, inv);
            }
            if (!h) variants('\\a' + fn, inv);
            variants('\\arc' + fn, inv);
            variants('Math.a' + fn, inv);
            variants('Math.arc' + fn, inv);
        }
    }
    return out;
}
